// v1.0.0.02
// Open Packaging structure extracted directly from your designed letterhead_template.docx
const LETTERHEAD_BASE64_DATA = "";

Office.onReady((info) => {
    if (info.host === Office.HostType.Word) {
        const letterheadBtn = document.getElementById("apply-letterhead-btn");
        letterheadBtn.onclick = applyCorporateLetterhead;
    }
});

async function applyCorporateLetterhead() {
    const btn = document.getElementById("apply-letterhead-btn");
    const statusDiv = document.getElementById("status-message");
    
    statusDiv.innerText = "";
    statusDiv.className = "status-box";
    btn.disabled = true;
    btn.innerText = "Applying Layout...";

    try {
        await Word.run(async (context) => {
            const sections = context.document.sections;
            sections.load("items");
            await context.sync();

            const primaryHeader = sections.items[0].getHeader("Primary");
            const primaryFooter = sections.items[0].getFooter("Primary");

            // Complete wipe out prevents multi-image overlapping corruption
            primaryHeader.clear();
            primaryFooter.clear();

            // Inject the underlying word processing structures safely
            primaryHeader.insertFileFromBase64(LETTERHEAD_BASE64_DATA, "Replace");
            primaryFooter.insertFileFromBase64(LETTERHEAD_BASE64_DATA, "Replace");

            await context.sync();
        });
        
        btn.innerText = "Letterhead Applied!";
        statusDiv.innerText = "Success: Header and footer elements updated.";
        statusDiv.className = "status-box success";
        
    } catch (error) {
        console.error("Pipeline failure: " + error);
        btn.innerText = "Apply Letterhead";
        statusDiv.innerText = "Error: Layout generation failed. Please contact your system admin.";
        statusDiv.className = "status-box error";
    } finally {
        btn.disabled = false;
    }
}

